   437	/* ============ 起卦逻辑（与 scripts/divine.py 对齐） ============ */
   438	async function sha256Hex(str){
   439	  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(str));
   440	  return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,"0")).join("");
   441	}
   442	async function stableInt(parts, mod){
   443	  const hex = await sha256Hex(parts.join("::"));
   444	  return Number(BigInt("0x"+hex) % BigInt(mod));
