# 关键：把 RUN 初始化改为展示脚本确定的这一卦（cheer=1 / witch-1），并把 blessing 注入到建议区
# 1) 在脚本底部 run(TODAY, "") 处，改为用预置结果渲染
init_code = r'''run(TODAY, "");'''
replacement_init = r'''
/* —— 小巫女起卦结果已由 divine.py（cheer=1, salt=witch-1）确定 —— */
const PRESET = __DIVINE_JSON__;
function renderPreset(){
  const lines = PRESET.lines.map(l => l.value);
  const movingIdx = PRESET.lines.map((l,i)=>({v:l.value,i})).filter(o=>o.v===6||o.v===9).map(o=>o.i);
  const result = {
    dateStr: PRESET.date,
    salt: PRESET.salt,
    lines,
    movingIdx,
    original: {
      number: PRESET.original_hexagram.number,
      name: PRESET.original_hexagram.name,
      gist: PRESET.original_hexagram.gist,
      level: PRESET.original_hexagram.level,
      level_word: PRESET.original_hexagram.level_word,
      symbol: PRESET.original_hexagram.symbol,
      upper_trigram: PRESET.original_hexagram.upper_trigram,
      lower_trigram: PRESET.original_hexagram.lower_trigram
    },
    changed: PRESET.changed_hexagram ? {
      number: PRESET.changed_hexagram.number,
      name: PRESET.changed_hexagram.name,
      gist: PRESET.changed_hexagram.gist,
      level: PRESET.changed_hexagram.level,
      level_word: PRESET.changed_hexagram.level_word,
      symbol: PRESET.changed_hexagram.symbol
    } : null,
    fortune: PRESET.fortune,
    colorName: PRESET.lucky_color,
    colorHex: (COLOR_BY_ELEMENT[PRESET.original_hexagram.upper_trigram.element] || []).find(([n,h])=>n===PRESET.lucky_color)?.[1] || "#c9a227",
    luckyNumber: PRESET.lucky_number,
    advice: PRESET.advice,
    blessing: PRESET.blessing || ""
  };
  renderResult(result);
  if(result.blessing){
    const line = document.getElementById("blessingLine");
    if(line){
      line.textContent = result.blessing;
      line.classList.add("show");
    }
  }
}
renderPreset();'''

html = html.replace(init_code, replacement_init)
html = html.replace("__DIVINE_JSON__", json.dumps(divine_json, ensure_ascii=False))

# 2) 在 DOM 里加 blessing 行（放在 advice-line 上方）
