  <div class="advice-line" id="adviceLine"><b>今日建议</b> · <span id="adviceText">—</span></div>'''
html = html.replace(
  '''<div class="advice-line" id="adviceLine"><b>今日建议</b> · <span id="adviceText">—</span></div>''',
  blessing_html
)

# 3) 加 blessing 的样式
blessing_css = '''
  .blessing-line{
    text-align:center;
    font-size:13.5px;
    color:var(--gold);
    margin-bottom:12px;
    letter-spacing:0.03em;
    opacity:0;
    transform:translateY(8px);
    transition:opacity 0.6s ease 0.35s, transform 0.6s ease 0.35s;
  }
  .blessing-line.show{ opacity:1; transform:translateY(0); }
'''
html = html.replace("  .advice-line{", blessing_css + "\n  .advice-line{")

